import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

const Cart = () => {
    const [cartItems, setCartItems] = useState([]);
    const { user } = useAuth();
    const navigate = useNavigate();

    useEffect(() => {
        const items = JSON.parse(localStorage.getItem('bindass_cart')) || [];
        setCartItems(items);
    }, []);

    const subtotal = cartItems.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const tax = subtotal * 0.08;

    const removeItem = (cartId) => {
        const updated = cartItems.filter(item => item.cartId !== cartId);
        setCartItems(updated);
        localStorage.setItem('bindass_cart', JSON.stringify(updated));
        window.dispatchEvent(new Event('storage'));
    };

    const handleCheckout = async () => {
        if (!user) {
            alert("Please sign in to complete your luxury purchase.");
            return;
        }

        try {
            // 1. Get the secure Firebase Token
            const token = await user.getIdToken();

            // 2. Create the Order on your Node.js server
            // This hits your /api/payments/create-order route
            const { data: order } = await axios.post(
                'http://localhost:5000/api/payments/create-order',
                { amount: subtotal + tax }, // Total amount including tax
                { headers: { Authorization: `Bearer ${token}` } }
            );

            // 3. Configure Razorpay Modal Options
            const options = {
                key: "YOUR_RAZORPAY_KEY_ID", // Paste your rzp_test_... key here
                amount: order.amount,
                currency: order.currency,
                name: "BINDASS!! Co.",
                description: "Luxury Apparel Acquisition",
                image: "https://your-logo-url.com/logo.png", // Optional: your logo
                order_id: order.id,
                handler: async (response) => {
                    try {
                        // 4. Send verification data to backend
                        const verifyData = {
                            razorpay_order_id: response.razorpay_order_id,
                            razorpay_payment_id: response.razorpay_payment_id,
                            razorpay_signature: response.razorpay_signature,
                            cart: cartItems // Pass cart details for n8n processing
                        };

                        await axios.post(
                            'http://localhost:5000/api/payments/verify-payment',
                            verifyData,
                            { headers: { Authorization: `Bearer ${token}` } }
                        );

                        // 5. Success Action
                        localStorage.removeItem('bindass_cart');
                        window.dispatchEvent(new Event('storage'));
                        alert("Payment Successful! Your luxury pieces are being prepared.");
                        window.location.href = "/profile";
                    } catch (err) {
                        console.error("Verification failed:", err);
                        alert("Payment verification failed. Please contact support.");
                    }
                },
                prefill: {
                    name: user.displayName,
                    email: user.email,
                },
                theme: {
                    color: "#10221c" // Matches your Lacoste-inspired dark green
                }
            };

            const rzp = new window.Razorpay(options);
            rzp.open();

        } catch (error) {
            console.error("Checkout initialization failed:", error);
            alert("Could not initiate checkout. Is the server running?");
        }
    };

    return (
        <main className="max-w-7xl mx-auto px-6 py-12 font-['Manrope']">
            <h1 className="text-3xl font-extrabold uppercase tracking-tighter mb-12">Your Shopping Bag ({cartItems.length})</h1>
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                <div className="lg:col-span-8 space-y-8">
                    {cartItems.map((item) => (
                        <div key={item.cartId} className="flex gap-6 pb-8 border-b border-slate-100">
                            <div className="w-32 h-40 bg-slate-50 rounded overflow-hidden">
                                <img src={item.image} className="w-full h-full object-cover" alt={item.name} />
                            </div>
                            <div className="flex-1 flex flex-col justify-between">
                                <div className="flex justify-between">
                                    <h3 className="font-bold uppercase text-sm tracking-tight">{item.name}</h3>
                                    <p className="font-bold">₹{item.price.toLocaleString()}</p>
                                </div>
                                <p className="text-xs text-slate-400 uppercase">Size: {item.size}</p>
                                <button onClick={() => removeItem(item.cartId)} className="text-[10px] uppercase font-bold text-red-500 underline underline-offset-4 w-fit">Remove</button>
                            </div>
                        </div>
                    ))}
                </div>
                <div className="lg:col-span-4 bg-[#f8f9f8] p-8 h-fit sticky top-24">
                    <h2 className="text-xs font-bold uppercase tracking-widest mb-8">Summary</h2>
                    <div className="space-y-4 text-sm border-b pb-6">
                        <div className="flex justify-between"><span>Subtotal</span><span>₹{subtotal.toLocaleString()}</span></div>
                        <div className="flex justify-between"><span>Tax (8%)</span><span>₹{tax.toLocaleString()}</span></div>
                    </div>
                    <div className="flex justify-between py-6 font-bold text-xl"><span>Total</span><span>₹{(subtotal + tax).toLocaleString()}</span></div>
                    <button onClick={handleCheckout} className="w-full bg-[#10221c] text-white py-5 uppercase text-[10px] font-bold tracking-[0.3em] hover:bg-black transition-all">Proceed to Checkout</button>
                </div>
            </div>
        </main>
    );
};

export default Cart;
